window.PLI_LOGO_APPLY = async function(){
  var D = window.PLI_LOGO, T = {edu:'Education', work:'Work Experience', aw:'Honors &amp; Awards'};
  var r = await PLI_EDIT('<h3>Education</h3>', function(h){
    if (h.indexOf('/*pli-logo*/') < 0) {
      var i = h.indexOf('.pli-roles{'); if (i < 0) i = h.indexOf('</style>'); if (i < 0) throw new Error('no css anchor');
      h = h.slice(0, i) + D.css + h.slice(i);
    }
    Object.keys(T).forEach(function(k){
      var re = new RegExp('<section class="pli-card"><h3>' + T[k].replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '</h3>[\\s\\S]*?</section>');
      if (!re.test(h)) throw new Error('no section ' + k);
      h = h.replace(re, function(){ return D.secs[k]; });
    });
    return h;
  });
  var b = [].slice.call(document.querySelectorAll('button')).find(function(x){ return x.textContent.trim() === '게시'; });
  if (!b) throw new Error('no publish button'); b.click();
  return JSON.stringify(r);
};
